import{_ as a,o as e,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Disconnect Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/publishing-social/3-8-2-disconnect-account/spec.md","filePath":"feature/publishing-social/3-8-2-disconnect-account/spec.md"}'),c={name:"feature/publishing-social/3-8-2-disconnect-account/spec.md"};function o(r,t,h,l,s,d){return e(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="uc-—-disconnect-account" tabindex="-1">UC — Disconnect Account <a class="header-anchor" href="#uc-—-disconnect-account" aria-label="Permalink to &quot;UC — Disconnect Account&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.8.2</td></tr><tr><td>Feature</td><td>Disconnect Account</td></tr><tr><td>Domain</td><td>Publishing &amp; Social (FR 3.8)</td></tr><tr><td>Role</td><td>CLIENT</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Ngắt kết nối tài khoản social, log out khỏi mạng xã hội.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Client, tôi muốn ngắt kết nối tài khoản social, khi tôi không muốn Agency đăng bài thay tôi nữa.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Revoke token phía platform (nếu API hỗ trợ) + xóa/deactivate record <code>SocialAccount</code> phía hệ thống.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Nút &#39;Ngắt kết nối&#39; trong <code>/workspaces/:id/social-accounts</code>.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/v1/social/accounts/{accountId}</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: null }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Không phải Client sở hữu account này → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Disconnect khi đang có Post <code>PENDING</code> chờ publish qua tài khoản này → Post đó chuyển <code>FAIL</code> với lý do rõ ràng (account disconnected), không publish ngầm.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Disconnect thành công, các Post pending qua account này được xử lý đúng (fail rõ lý do).</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a></p>`,22)])])}const b=a(c,[["render",o]]);export{p as __pageData,b as default};
